<?php
function inventory_update_ready(){return setting('workflow_version','')==='5.1';}
function inventory_write_lock(){global $CFG;$name='rs8-stock-'.substr(hash('sha256',$CFG['db_name']),0,30);$q=db()->prepare('SELECT GET_LOCK(?,10)');$q->execute([$name]);if((int)$q->fetchColumn()!==1)throw new Exception('Another inventory update is in progress. Please try again.');return $name;}
function inventory_write_unlock($name){if($name){$q=db()->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$name]);}}
function count_stock_signature($pid){
 $parts=[];foreach(['beginning_balances','inflows','outflows','non_sellable','nonsellable_outflows','platform_stock'] as $table){$q=db()->prepare("SELECT * FROM $table WHERE product_id=? ORDER BY ".($table==='platform_stock'?'platform':'id'));$q->execute([$pid]);$parts[$table]=$q->fetchAll();}$q=db()->prepare('SELECT l.* FROM nonsellable_release_links l JOIN nonsellable_outflows o ON o.id=l.release_id WHERE o.product_id=? ORDER BY l.release_id,l.non_sellable_id');$q->execute([$pid]);$parts['release_links']=$q->fetchAll();$q=db()->prepare('SELECT * FROM stock_events WHERE product_id=? ORDER BY id');$q->execute([$pid]);$parts['events']=$q->fetchAll();return hash('sha256',json_encode($parts));
}
function count_create_snapshot_legacy($filters){
 global $selectedBrand,$selectedMain,$selectedSub;$selectedBrand=trim($filters['brand']??'');$selectedMain=trim($filters['main_category']??'');$selectedSub=trim($filters['subcategory']??'');$search=norm($filters['q']??'');$status=$filters['status']??'';
 if($selectedBrand!==''&&!in_array($selectedBrand,inventory_brand_options(),true))throw new Exception('Invalid brand filter.');
 $pdo=db();$own=!$pdo->inTransaction();if($own)$pdo->beginTransaction();try{
  $items=[];foreach(inventory_filtered_products(product_options()) as $p){if(isset($filters['product_ids'])&&!in_array((int)$p['id'],$filters['product_ids'],true))continue;if($search!==''&&!str_contains(norm($p['name'].' '.$p['brand'].' '.$p['master_sku']),$search))continue;$s=stock_row($p['id']);$key=stock_status_key(detect_status($s['current'],$p['low_stock_threshold'])[0]);if($status!==''&&$status!==$key)continue;$items[]=[$p,$s];}
  if(!$items)throw new Exception('No products match these filters.');$ref=next_ref('COUNT').'-'.bin2hex(random_bytes(3));$u=current_user();
  $pdo->prepare('INSERT INTO inventory_count_batches(batch_ref,status,filter_json,created_by,created_name,created_role) VALUES(?,?,?,?,?,?)')->execute([$ref,'Exported',json_encode($filters),$u['id'],$u['name'],$u['role']]);$id=(int)$pdo->lastInsertId();if(process_ready())$pdo->prepare('UPDATE inventory_count_batches SET count_date=? WHERE id=?')->execute([process_date($filters['count_date']??date('Y-m-d')),$id]);
  $insert=$pdo->prepare('INSERT INTO inventory_count_lines(batch_id,product_id,master_sku,product_name,on_hand,sellable_on_hand,nonsellable_on_hand,stock_signature) VALUES(?,?,?,?,?,?,?,?)');foreach($items as [$p,$s])$insert->execute([$id,$p['id'],$p['master_sku'],$p['name'],$s['physical'],$s['current'],$s['nonsellable'],count_stock_signature($p['id'])]);
  audit('Export inventory count','Inventory Count',$ref,count($items).' filtered products; physical on-hand snapshot.');if($own)$pdo->commit();return $id;
 }catch(Throwable $e){if($own&&$pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function count_batch($id){$q=db()->prepare('SELECT * FROM inventory_count_batches WHERE id=?');$q->execute([(int)$id]);$r=$q->fetch();if(!$r)throw new Exception('Inventory count sheet not found.');return $r;}
function count_lines($id){$q=db()->prepare('SELECT * FROM inventory_count_lines WHERE batch_id=? ORDER BY id');$q->execute([(int)$id]);return $q->fetchAll();}
function count_upload_rows($id,$rows,$filename){if(adjustments_ready()&&adjustment_is_new($id))return adjustment_upload($id,$rows,$filename);return process_ready()?count_condition_upload($id,$rows,$filename):count_upload_legacy($id,$rows,$filename);}
function count_upload_legacy($id,$rows,$filename){
 $b=count_batch($id);if(in_array($b['status'],['Applied','Cancelled','Reversed'],true))throw new Exception('This inventory count is closed. Create a new sheet.');$pdo=db();$errors=[];$actuals=[];$seen=[];$lines=count_lines($id);$known=[];foreach($lines as $line)$known[$line['master_sku']]=$line;
 if(($rows[0][0]??'')!=='Physical Inventory Count'||trim($rows[0][1]??'')!==$b['batch_ref'])$errors[]='This file belongs to a different count sheet. Use the original downloaded file.';
 $header=find_header_row($rows,[['Master SKU','Product Description','On Hand','Actual Count','Variance','Remarks']]);
 if($header===null)$errors[]='Required column headers are missing. Do not rename them.';
 else{ $keys=array_map('norm',$rows[$header]);$col=array_flip($keys);
  foreach(array_slice($rows,$header+1) as $i=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;$n=$header+$i+2;$sku=trim($row[$col['master sku']]??'');if(!isset($known[$sku])){$errors[]="Row $n: unknown SKU $sku for this sheet.";continue;}if(isset($seen[$sku])){$errors[]="Row $n: duplicate SKU $sku.";continue;}$seen[$sku]=true;$line=$known[$sku];
   $on=trim($row[$col['on hand']]??'');if(!is_numeric($on)||(float)$on!=(int)$line['on_hand'])$errors[]="Row $n: On Hand snapshot was changed for $sku.";
   $value=trim($row[$col['actual count']]??'');if($value==='')continue;
   if(!preg_match('/^\d+$/D',$value)||strlen($value)>9||(int)$value>100000000){$errors[]="Row $n: Actual Count must be a non-negative whole number for $sku.";continue;}
   $actuals[$line['id']]=[(int)$value,trim($row[$col['remarks']]??'')];
  }
 }
 if(!$actuals&&!$errors)$errors[]='Enter at least one Actual Count. Blank cells are not zero.';
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT status FROM inventory_count_batches WHERE id=? FOR UPDATE');$q->execute([$id]);if($q->fetchColumn()==='Applied')throw new Exception('This count was already applied.');
  if(process_ready())$pdo->prepare('UPDATE inventory_count_lines SET actual_good=NULL,actual_damaged=NULL,good_variance=NULL,damaged_variance=NULL WHERE batch_id=?')->execute([$id]);$pdo->prepare('UPDATE inventory_count_lines SET actual_count=NULL,variance=NULL,remarks=NULL WHERE batch_id=?')->execute([$id]);$q=$pdo->prepare('UPDATE inventory_count_lines SET actual_count=?,variance=?-on_hand,remarks=? WHERE id=? AND batch_id=?');foreach($actuals as $lineId=>[$value,$remarks])$q->execute([$value,$value,$remarks,$lineId,$id]);
  $u=current_user();$pdo->prepare('UPDATE inventory_count_batches SET status=?,filename=?,error_json=?,reviewed_by=?,reviewed_name=?,reviewed_role=?,reviewed_at=NOW(),approved_by=NULL,approved_name=NULL,approved_role=NULL WHERE id=?')->execute([$errors?'Error':'Pending Review',basename($filename),json_encode($errors),$u['id'],$u['name'],$u['role'],$id]);audit('Upload inventory count','Inventory Count',$b['batch_ref'],count($actuals).' actual counts; '.count($errors).' errors.');$pdo->commit();return $errors;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function count_apply($id,$reason,$allocations=[]){if(adjustments_ready()&&adjustment_is_new($id))throw new Exception('Use the separate recount, review and Admin approval workflow.');return process_ready()?count_condition_apply($id,$reason,$allocations):count_apply_legacy($id,$reason,$allocations);}
function count_apply_legacy($id,$reason,$allocations=[]){
 if(current_user()['role']!=='Admin')throw new Exception('Administrator approval is required.');if(trim($reason)==='')throw new Exception('Enter the adjustment reason.');
 $pdo=db();$pdo->beginTransaction();try{
  $q=$pdo->prepare('SELECT * FROM inventory_count_batches WHERE id=? FOR UPDATE');$q->execute([$id]);$b=$q->fetch();if(!$b||!in_array($b['status'],['Pending Review','Review Only'],true))throw new Exception('This count is not ready to apply or was already applied.');
  $lines=count_lines($id);$count=0;$plans=[];foreach($lines as $line){if($line['actual_count']===null)continue;$count++;$pid=(int)$line['product_id'];$lock=$pdo->prepare('SELECT id,active FROM products WHERE id=? FOR UPDATE');$lock->execute([$pid]);$p=$lock->fetch();if(!$p||!$p['active'])throw new Exception('A counted product is inactive. Review the sheet again.');
   if(!hash_equals($line['stock_signature'],count_stock_signature($pid)))throw new Exception('Stock movements changed after this sheet was downloaded: '.$line['master_sku'].'. Download a fresh sheet and recount/review.');
   $s=stock_row($pid);$actual=(int)$line['actual_count'];$newSellable=$actual-$s['nonsellable'];if($newSellable<0)throw new Exception('Actual Count is below Non-Sellable stock for '.$line['master_sku'].'. Review non-sellable records first.');check_platform_alignment($pid);$variance=(int)$line['variance'];$rows=[$pid=>['name'=>$line['product_name'],'qty'=>abs($variance),'damaged'=>false]];$plans[$pid]=incoming_plan($rows,[$pid=>$allocations[$pid]??[]])[$pid];
  }
  if(!$count)throw new Exception('No actual counts to apply.');$u=current_user();foreach($lines as $line){if($line['actual_count']===null)continue;$delta=(int)$line['variance'];if(!$delta)continue;$pid=(int)$line['product_id'];
   if($delta>0)$pdo->prepare('INSERT INTO inflows(txn_date,reference_no,product_id,source_qty,source_uom,conversion_factor,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([date('Y-m-d'),$b['batch_ref'],$pid,$delta,'pc',1,$delta,'Inventory Count Adjustment',$reason,$u['id']]);
   else $pdo->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([date('Y-m-d'),'Internal',$b['batch_ref'],$pid,-$delta,'Inventory Count Adjustment',$reason,$u['id']]);
   foreach(['Shopee','Lazada','TikTok'] as $pl)if($plans[$pid][$pl])change_platform_stock($pl,$pid,($delta<0?-1:1)*$plans[$pid][$pl],$b['batch_ref'],date('Y-m-d'));check_platform_alignment($pid);
   audit('Inventory count adjustment','Product',$line['master_sku'],'Physical '.$line['on_hand'].' → '.$line['actual_count'].'; variance '.$delta.'; '.$b['batch_ref'].'; '.$reason.'; Reviewed platform quantities '.json_encode($plans[$pid]));
  }
  $pdo->prepare("UPDATE inventory_count_batches SET status='Applied',approved_by=?,approved_name=?,approved_role=?,applied_at=NOW(),reason=? WHERE id=?")->execute([$u['id'],$u['name'],$u['role'],$reason,$id]);$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function count_export_xlsx($id,$path){if(adjustments_ready()&&adjustment_is_new($id))return adjustment_export($id,$path);
 $b=count_batch($id);$lines=count_lines($id);$xmlEscape=fn($s)=>htmlspecialchars((string)$s,ENT_XML1|ENT_QUOTES,'UTF-8');$cell=function($ref,$value,$style=0,$numeric=false)use($xmlEscape){return $numeric?'<c r="'.$ref.'" s="'.$style.'"><v>'.(int)$value.'</v></c>':'<c r="'.$ref.'" t="inlineStr" s="'.$style.'"><is><t xml:space="preserve">'.$xmlEscape($value).'</t></is></c>';};
 $sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0"><pane ySplit="4" topLeftCell="A5" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="24" customWidth="1"/><col min="2" max="2" width="65" customWidth="1"/><col min="3" max="5" width="18" customWidth="1"/><col min="6" max="6" width="18" customWidth="1"/><col min="7" max="7" width="35" customWidth="1"/></cols><sheetData><row r="1">'.$cell('A1','Physical Inventory Count',1).$cell('B1',$b['batch_ref']).'</row><row r="2">'.$cell('A2','Count Date').$cell('B2',$b['count_date']??substr($b['created_at'],0,10)).'</row><row r="3">'.$cell('A3','Fill Actual Good and Actual Damaged; leave uncounted rows blank. Use 0 for zero. Remarks required for discrepancies.').'</row><row r="4">';foreach(['Master SKU','Product Description','On Hand','Actual Good','Actual Damaged','Variance','Remarks'] as $i=>$name)$sheet.=$cell(XlsxReader::colLetters($i).'4',$name,1);$sheet.='</row>';
 foreach($lines as $i=>$line){$r=$i+5;$sheet.='<row r="'.$r.'">'.$cell('A'.$r,$line['master_sku']).$cell('B'.$r,$line['product_name'],2).$cell('C'.$r,$line['on_hand'],2,true).$cell('D'.$r,'',3).$cell('E'.$r,'',3).$cell('F'.$r,'',2).$cell('G'.$r,'',3).'</row>';}
 $sheet.='</sheetData><autoFilter ref="A4:G'.(count($lines)+4).'"/><mergeCells count="1"><mergeCell ref="A3:G3"/></mergeCells><printOptions horizontalCentered="1"/><pageMargins left="0.25" right="0.25" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>';
 $z=new ZipArchive();if($z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new Exception('Cannot generate count workbook.');
 $z->addFromString('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
 $z->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
 $z->addFromString('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Inventory Count" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="_xlnm.Print_Titles" localSheetId="0">\'Inventory Count\'!$1:$4</definedName></definedNames></workbook>');
 $z->addFromString('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
 $z->addFromString('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Arial"/></font></fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF142235"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFF6D9"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="4"><xf fontId="0" fillId="0" borderId="0" xfId="0"/><xf fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1"/><xf fontId="0" fillId="0" borderId="0" xfId="0"><alignment wrapText="1" vertical="top"/></xf><xf fontId="0" fillId="3" borderId="0" xfId="0" applyFill="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
 $z->addFromString('xl/worksheets/sheet1.xml',$sheet);$z->close();
}

function count_cancel_pending($id){if(!can_action('upload_inventory_count'))throw new Exception('Permission required.');return process_transaction(function()use($id){$q=db()->prepare('SELECT * FROM inventory_count_batches WHERE id=? FOR UPDATE');$q->execute([$id]);$b=$q->fetch();if(!$b||in_array($b['status'],['Applied','Cancelled','Reversed'],true))throw new Exception('Count is already applied or cancelled.');db()->prepare("UPDATE inventory_count_batches SET status='Cancelled' WHERE id=?")->execute([$id]);audit('Cancel inventory count','Inventory Count',$b['batch_ref'],'No stock changed.');});}

function count_create_snapshot($filters){return adjustments_ready()?adjustment_create($filters):count_create_snapshot_legacy($filters);}

